class Solution {
public:
    int dietPlanPerformance(vector<int>& calories, int k,
                            int lower, int upper) {
        int sum = 0;
        int score = 0;
        for (int i = 0; i < static_cast<int>(calories.size()); ++i) {
            sum += calories[i];
            if (i >= k) {
                sum -= calories[i - k];
            }
            if (i >= k - 1) {
                score += (sum < lower ? -1 : (sum > upper ? 1 : 0));
            }
        }
        return score;
    }
};
